import { colonIndexInBetween } from "../colonIndexInBetween/index.js";
import { declarationColonSource } from "../declarationColonSource/index.js";
import { declarationValueAsSpelled } from "../declarationValueAsSpelled/index.js";
import { declarationValueIndex } from "../declarationValueIndex/index.js";
import { findEscapeSpans } from "../findCommentSpans/index.js";
import { maskEscapes } from "../maskEscapes/index.js";
import { report } from "../report/index.js";
import { runInFront } from "../runInFront/index.js";
/**
 * Checks the whitespace beside the colon of every declaration.
 * @param opts - The options.
 */
export function declarationColonSpaceChecker(opts) {
    let { fix } = opts;
    opts.root.walkDecls((decl) => {
        if (!opts.syntax.isStandardDeclaration(decl))
            return;
        // Another plugin's declaration has no `raws.between`
        if (!decl.raws.between)
            return;
        // The rule's own filter
        if (opts.isChecked && !opts.isChecked(decl))
            return;
        let source = declarationColonSource(opts.syntax, decl, opts.result);
        // The run is read over the copy with its escapes masked, where an escaped space is a character of the property and no run, and the fix in front of the colon cuts that run
        let runString = maskEscapes(source, findEscapeSpans(source, opts.syntax.inlineComments(decl, opts.result)), true);
        // The first colon of `raws.between` outside a comment, string or parentheses
        let indexInBetween = colonIndexInBetween(opts.syntax, decl, opts.result);
        if (indexInBetween === -1)
            return;
        // Counted from the start of the declaration
        let startIndex = declarationValueIndex(decl) - decl.raws.between.length + indexInBetween;
        let problemIndex = decl.prop.toString().length + 1;
        // The rule's own fix guard
        let isFixable = fix && (!opts.isFixable || opts.isFixable(decl, startIndex, source, runString));
        opts.locationChecker({
            source: runString,
            index: startIndex,
            // `decl.value` drops comments, and a break inside one with them
            lineCheckStr: declarationValueAsSpelled(opts.syntax, decl, opts.result),
            err: (message) => {
                report({
                    message,
                    node: decl,
                    index: problemIndex,
                    endIndex: problemIndex,
                    result: opts.result,
                    ruleName: opts.checkedRuleName,
                    ...(fix && isFixable && { fix: () => fix(decl, startIndex, runInFront(runString, startIndex)) }),
                });
            },
        });
    });
}
